begin;
create extension if not exists pgtap with schema extensions;
select plan(65);
select has_table('public','services','services exists');
select has_table('public','proposals','proposals exists');
select has_table('public','proposal_items','proposal items exists');
select col_type_is('public','services','default_price','numeric(14,2)','service money is numeric');
select col_type_is('public','proposal_items','quantity','numeric(12,3)','quantity supports fractions');
select col_type_is('public','proposals','total_amount','numeric(14,2)','proposal total is numeric');
select ok(not has_table_privilege('anon','public.services','SELECT'),'anon cannot read services');
select ok(not has_table_privilege('authenticated','public.proposals','INSERT'),'authenticated cannot bypass proposal RPC');
select ok(not has_table_privilege('authenticated','public.proposal_items','UPDATE'),'authenticated cannot bypass item RPC');

insert into public.organizations(id,name,slug) values ('60000000-0000-4000-8000-000000000001','D1 A','d1-a'),('60000000-0000-4000-8000-000000000002','D1 B','d1-b');
insert into auth.users(id,email,created_at,updated_at) values
('60000000-0000-4000-8000-000000000011','writer@example.invalid',now(),now()),('60000000-0000-4000-8000-000000000012','reader@example.invalid',now(),now());
insert into public.organization_members(id,organization_id,user_id,status) values
('60000000-0000-4000-8000-000000000021','60000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000011','active'),('60000000-0000-4000-8000-000000000022','60000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000012','active');
insert into public.organization_member_roles(organization_id,membership_id,role_id) select m.organization_id,m.id,r.id from public.organization_members m join public.roles r on r.organization_id=m.organization_id and r.slug='colaborador' where m.id='60000000-0000-4000-8000-000000000021';
insert into public.roles(id,organization_id,name,slug,description) values('60000000-0000-4000-8000-000000000031','60000000-0000-4000-8000-000000000001','Leitor D1','leitor-d1','Le propostas');
insert into public.role_permissions(role_id,permission_id) select '60000000-0000-4000-8000-000000000031',id from public.permissions where key='proposals.read';
insert into public.organization_member_roles(organization_id,membership_id,role_id) values('60000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000022','60000000-0000-4000-8000-000000000031');
insert into public.leads(id,organization_id,full_name,email,service_interest,message,source,landing_path,status,consent_version) values('60000000-0000-4000-8000-000000000041','60000000-0000-4000-8000-000000000001','Lead D1','lead@example.invalid','other','Contexto sintetico suficientemente longo.','outbound','/crm/manual','new','manual');
insert into public.opportunities(id,organization_id,lead_id,stage_id,title,created_by,updated_by) select '60000000-0000-4000-8000-000000000051','60000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000041',id,'Oportunidade D1','60000000-0000-4000-8000-000000000011','60000000-0000-4000-8000-000000000011' from public.pipeline_stages where organization_id='60000000-0000-4000-8000-000000000001' and position=1;
insert into public.clients(id,organization_id,source_lead_id,source_opportunity_id,created_by) values('60000000-0000-4000-8000-000000000061','60000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000041','60000000-0000-4000-8000-000000000051','60000000-0000-4000-8000-000000000011');
insert into public.client_opportunities(client_id,organization_id,opportunity_id,linked_by) values('60000000-0000-4000-8000-000000000061','60000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000051','60000000-0000-4000-8000-000000000011');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::integer from public.services),0,'AAL1 cannot read services');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.create_service('Servico sintetico','Descricao','project',1500)$$,'writer creates service');
select is((select count(*)::integer from public.services),1,'service persisted');
select throws_ok($$select public.create_service('Preco negativo','Descricao','hour',-1)$$,'23514',null,'negative service price is rejected');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000012","role":"authenticated","aal":"aal2"}',true);
select is((select count(*)::integer from public.services),1,'proposal reader reads own catalog');
select throws_ok($$select public.create_service('Negado','Descricao','unit',1)$$,'P0001','Proposal operation not permitted.','reader cannot write catalog');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.create_proposal('60000000-0000-4000-8000-000000000061','60000000-0000-4000-8000-000000000051','Proposta sintetica',current_date+30)$$,'writer creates proposal');
select matches((select proposal_number from public.proposals),'^DEV-[0-9]{4}-0001$','human number generated');
select is((select currency from public.proposals),'BRL','currency is BRL');
select lives_ok($$select public.save_proposal_item((select id from public.proposals),null,(select id from public.services),'','','1.5',null, null)$$,'catalog item uses defaults');
select is((select subtotal from public.proposals),2250.00::numeric,'subtotal calculated in database');
select is((select name from public.proposal_items),'Servico sintetico','item stores service snapshot');
select lives_ok($$select public.update_service((select id from public.services),'Servico alterado','Nova descricao','project',3000,false)$$,'service can be deactivated');
select is((select name from public.proposal_items),'Servico sintetico','service change does not alter snapshot');
select lives_ok($$select public.save_proposal_item((select id from public.proposals),null,null,'Item personalizado','Descricao custom','2','hour',100)$$,'custom item works');
select is((select count(*)::integer from public.proposal_items),2,'two items persisted');
select is((select subtotal from public.proposals),2450.00::numeric,'custom item recalculates subtotal');
select lives_ok($$select public.move_proposal_item((select id from public.proposal_items where service_id is null),-1)$$,'item can move up');
select is((select position from public.proposal_items where service_id is null),1,'reordering is deterministic');
select lives_ok($$select public.update_proposal((select id from public.proposals),'Proposta revisada',current_date+20,50)$$,'draft commercial data updates');
select is((select total_amount from public.proposals),2400.00::numeric,'discount recalculates total');
select throws_ok($$select public.update_proposal((select id from public.proposals),'Invalida',current_date,9999)$$,'23514','Invalid proposal discount.','discount above subtotal rejected');
select lives_ok($$select public.remove_proposal_item((select id from public.proposal_items where service_id is null))$$,'custom item can be removed');
select is((select count(*)::integer from public.proposal_items),1,'one item remains');
select is((select subtotal from public.proposals),2250.00::numeric,'removal recalculates subtotal');
select lives_ok($$select public.create_proposal('60000000-0000-4000-8000-000000000061',null,'Proposta recorrente',null)$$,'client can receive direct proposal');
select is((select count(distinct proposal_number)::integer from public.proposals),2,'numbers are unique');
set local role anon;
select throws_ok($$select count(*) from public.proposals$$,'42501',null,'anon reads no proposals');
select throws_ok($$insert into public.proposals(organization_id,proposal_number,client_id,title,created_by) values('60000000-0000-4000-8000-000000000001','DEV-2026-9999','60000000-0000-4000-8000-000000000061','Bypass','60000000-0000-4000-8000-000000000011')$$,'42501',null,'direct proposal insert denied');
reset role;
select throws_ok($$select public.create_proposal(gen_random_uuid(),null,'Cliente cruzado',null)$$,'23503','Client not available.','unknown or cross-tenant client is rejected');
select is((select count(*)::integer from public.services where not is_active),1,'inactive service is preserved');
select ok((select count(*) from public.audit_logs where action like 'proposal.%')>=6,'proposal audit events exist');
select ok(not exists(select 1 from public.audit_logs where metadata::text ~* 'email|phone|description'),'audit metadata excludes PII');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.prosecdef and not ('search_path=""'=any(coalesce(p.proconfig,array[]::text[])))),'security definer functions have safe search path');
select has_table('public','proposal_sections','proposal sections exist');
select has_table('public','organization_document_settings','document settings exist');
select ok((select relrowsecurity from pg_class where oid='public.proposal_sections'::regclass),'sections RLS enabled');
select ok(not has_table_privilege('anon','public.proposal_sections','SELECT'),'anon cannot read sections');
select ok(not has_table_privilege('authenticated','public.proposal_sections','INSERT'),'authenticated cannot bypass section RPC');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::integer from public.proposal_sections),0,'AAL1 cannot read sections');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000012","role":"authenticated","aal":"aal2"}',true);
select is((select count(*)::integer from public.proposal_sections),18,'reader reads own default sections');
select throws_ok($$select public.save_proposal_section((select id from public.proposals limit 1),null,'custom','Negada','texto',true)$$,'P0001','Proposal operation not permitted.','reader cannot write sections');
select set_config('request.jwt.claims','{"sub":"60000000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.save_proposal_section((select id from public.proposals order by created_at limit 1),null,'custom','Garantia','Texto sintetico',true)$$,'writer creates custom section');
select is((select title from public.proposal_sections where section_type='custom'),'Garantia','custom title persists');
select lives_ok($$select public.save_proposal_section((select proposal_id from public.proposal_sections where section_type='custom'),(select id from public.proposal_sections where section_type='custom'),'custom','Garantia revisada','Novo texto',false)$$,'writer updates section');
select is((select is_visible from public.proposal_sections where section_type='custom'),false,'visibility persists');
select throws_ok($$select public.save_proposal_section((select id from public.proposals limit 1),null,'custom','','texto',true)$$,'23514',null,'empty custom title rejected');
select throws_ok($$select public.save_proposal_section((select id from public.proposals limit 1),null,'custom','Longa',repeat('x',12001),true)$$,'23514',null,'content limit enforced');
select lives_ok($$select public.move_proposal_section((select id from public.proposal_sections where section_type='custom'),-1)$$,'section reorders atomically');
select is((select position from public.proposal_sections where section_type='custom'),9,'custom section moved');
select lives_ok($$select public.update_proposal_document_settings('Devora Teste','contato@example.invalid',null,'https://example.invalid','Sao Paulo',null)$$,'writer updates document settings');
select is((select display_name from public.organization_document_settings),'Devora Teste','document settings tenant derived');
select throws_ok($$select public.save_proposal_section(gen_random_uuid(),null,'custom','Cruzada','texto',true)$$,'23514','Proposal is not editable.','unknown proposal blocked');
select lives_ok($$select public.remove_proposal_section((select id from public.proposal_sections where section_type='custom'))$$,'section can be removed');
reset role;
select ok(not exists(select 1 from public.audit_logs where metadata::text ~* 'Novo texto|Garantia revisada|contato@example'),'section audit excludes content and PII');
select ok((select count(*) from public.audit_logs where metadata->>'area' in('section','document_settings'))>=5,'structural audit exists');
select * from finish();
rollback;
